package com.example.clothingshop.admin;
import org.springframework.stereotype.Service;
import java.util.*;
import java.time.*;
@Service
public class AdminSearchService {
 private final AdminRepository db;
 public AdminSearchService(AdminRepository db){this.db=db;}
 Object v(Map<String,String> f,String k){String s=f.get(k);return s==null||s.isBlank()?null:s;}
 Object day(Map<String,String> f,String k,boolean end){Object s=v(f,k);return s==null?null:java.sql.Date.valueOf(end?LocalDate.parse(s.toString()).plusDays(1):LocalDate.parse(s.toString()));}
 int page(Map<String,String> f){return Integer.parseInt(f.getOrDefault("page","1"));}
 String like(Map<String,String> f,String key){return "%"+f.getOrDefault(key,"").toLowerCase(Locale.ROOT)+"%";}
 public Object managers(Map<String,String> f){return db.rows("SELECT m.ID,m.USERNAME,m.FULL_NAME,m.EMAIL,m.STATUS,m.MANAGER_ROLE_ID,r.ROLE_CODE FROM MANAGER m JOIN MANAGER_ROLE r ON r.ID=m.MANAGER_ROLE_ID WHERE m.DELETE_FLAG=0 AND (LOWER(m.USERNAME) LIKE :q OR LOWER(m.FULL_NAME) LIKE :q) AND (:r IS NULL OR r.ROLE_CODE=:r) AND (:s IS NULL OR m.STATUS=:s) ORDER BY m.ID","q",like(f,"q"),"r",v(f,"role"),"s",v(f,"status"));}
 public Object categories(String q){return db.rows("SELECT * FROM (SELECT ID,CATEGORY_NAME,PARENT_ID,STATUS,CASE WHEN INSTR(SYS_CONNECT_BY_PATH(STATUS,'/'),'/0')>0 THEN 0 ELSE 1 END EFFECTIVE_STATUS,LEVEL DEPTH,SYS_CONNECT_BY_PATH(CATEGORY_NAME,' / ') CATEGORY_PATH FROM CATEGORY START WITH PARENT_ID IS NULL CONNECT BY NOCYCLE PRIOR ID=PARENT_ID ORDER SIBLINGS BY CATEGORY_NAME) WHERE LOWER(CATEGORY_PATH) LIKE :q","q","%"+q.toLowerCase(Locale.ROOT)+"%");}
 public Object categoryImpact(long id){return db.one("SELECT (SELECT COUNT(*)-1 FROM CATEGORY START WITH ID=:i CONNECT BY NOCYCLE PRIOR ID=PARENT_ID) CHILDREN,(SELECT COUNT(*) FROM PRODUCT WHERE DELETE_FLAG=0 AND CATEGORY_ID IN (SELECT ID FROM CATEGORY START WITH ID=:i CONNECT BY NOCYCLE PRIOR ID=PARENT_ID)) PRODUCTS FROM DUAL","i",id);}
 public Object vouchers(Map<String,String> f){return db.rows("SELECT * FROM (SELECT v.*,USAGE_LIMIT-USED_COUNT REMAINING,CASE WHEN STATUS=0 THEN 'DISABLED' WHEN LOCALTIMESTAMP<STARTS_AT THEN 'UPCOMING' WHEN LOCALTIMESTAMP>=ENDS_AT THEN 'EXPIRED' WHEN USED_COUNT>=USAGE_LIMIT THEN 'EXHAUSTED' ELSE 'ACTIVE' END EFFECTIVE_STATUS FROM VOUCHER v) WHERE LOWER(CODE) LIKE :q AND (:s IS NULL OR EFFECTIVE_STATUS=:s) ORDER BY ID DESC","q",like(f,"q"),"s",v(f,"effective"));}
 public Object voucherOrders(long id){return db.rows("SELECT b.ID,b.BILL_CODE,b.STATUS,b.DISCOUNT_AMOUNT,b.CREATED_AT FROM BILL b JOIN VOUCHER v ON v.CODE=b.VOUCHER_CODE WHERE v.ID=:i ORDER BY b.ID DESC","i",id);}
 public Object orders(Map<String,String> f){return db.page("SELECT ID,BILL_CODE,RECEIVER_NAME,TOTAL_AMOUNT,STATUS,PAYMENT_METHOD,PAYMENT_STATUS,RETURN_STATUS,CREATED_AT,DISPATCHED FROM BILL WHERE DELETE_FLAG=0 AND (LOWER(BILL_CODE) LIKE :q OR LOWER(RECEIVER_NAME) LIKE :q) AND (:s IS NULL OR STATUS=:s) AND (:pm IS NULL OR PAYMENT_METHOD=:pm) AND (:ps IS NULL OR PAYMENT_STATUS=:ps) AND (:rs IS NULL OR RETURN_STATUS=:rs) AND (:f IS NULL OR CREATED_AT>=:f) AND (:t IS NULL OR CREATED_AT<:t) ORDER BY ID DESC",page(f),20,"q",like(f,"q"),"s",v(f,"status"),"pm",v(f,"paymentMethod"),"ps",v(f,"paymentStatus"),"rs",v(f,"returnStatus"),"f",day(f,"from",false),"t",day(f,"to",true));}
 public Object history(Map<String,String> f){return db.page("SELECT h.ID,h.DOCUMENT_ID,h.PRODUCT_DETAIL_ID,v.SKU,p.PRODUCT_NAME,h.QUANTITY_CHANGE,h.REASON,m.USERNAME,h.BILL_ID,b.BILL_CODE,h.CREATED_AT,h.MOVEMENT_TYPE,h.BEFORE_QUANTITY,h.AFTER_QUANTITY,h.PHYSICAL_BEFORE,h.PHYSICAL_AFTER,h.RESERVED_BEFORE,h.RESERVED_AFTER,h.VALUE_BEFORE,h.VALUE_AFTER,h.HISTORY_SCOPE,d.DOC_CODE FROM INVENTORY_HISTORY h JOIN PRODUCT_DETAIL v ON v.ID=h.PRODUCT_DETAIL_ID JOIN PRODUCT p ON p.ID=v.PRODUCT_ID LEFT JOIN MANAGER m ON m.ID=h.MANAGER_ID LEFT JOIN BILL b ON b.ID=h.BILL_ID LEFT JOIN INVENTORY_DOCUMENT d ON d.ID=h.DOCUMENT_ID WHERE (LOWER(v.SKU) LIKE :q OR LOWER(p.PRODUCT_NAME) LIKE :q) AND (:v IS NULL OR v.ID=:v) AND (:kind IS NULL OR h.MOVEMENT_TYPE=:kind) AND (:f IS NULL OR h.CREATED_AT>=:f) AND (:t IS NULL OR h.CREATED_AT<:t) AND LOWER(NVL(d.DOC_CODE,' ')) LIKE :doc AND LOWER(NVL(b.BILL_CODE,' ')) LIKE :bill ORDER BY h.ID DESC",page(f),30,"q",like(f,"q"),"v",v(f,"variantId"),"kind",v(f,"type"),"f",day(f,"from",false),"t",day(f,"to",true),"doc",like(f,"document"),"bill",like(f,"bill"));}
 public Object audit(Map<String,String> f){return db.page("SELECT a.ID,m.USERNAME,a.ACTION,a.OBJECT_TYPE,a.OBJECT_ID,a.CREATED_AT,a.REASON,DBMS_LOB.SUBSTR(a.BEFORE_DATA,4000,1) BEFORE_DATA,DBMS_LOB.SUBSTR(a.AFTER_DATA,4000,1) AFTER_DATA FROM ADMIN_AUDIT a LEFT JOIN MANAGER m ON m.ID=a.MANAGER_ID WHERE LOWER(NVL(m.USERNAME,' ')) LIKE :q AND (:act IS NULL OR a.ACTION=:act) AND (:obj IS NULL OR a.OBJECT_TYPE=:obj) AND (:f IS NULL OR a.CREATED_AT>=:f) AND (:t IS NULL OR a.CREATED_AT<:t) ORDER BY a.ID DESC",page(f),30,"q",like(f,"q"),"act",v(f,"action"),"obj",v(f,"object"),"f",day(f,"from",false),"t",day(f,"to",true));}
}
